   exe=build/(tag+'-'+str(mutant));src=(lab if mutant=='stub' else ref)/'inactive_install.c';cmd=[*base,'-no-pie',src,lab/'inactive_install_test.c',*objects,'-o',exe]
   if mutant!='stub':cmd.append('-DFU_MUTANT='+str(mutant))
